'use strict';
/* test-setclass.js — the T/I group, and the harmonic vocabulary of a ternary space.
 *
 * Set `AE`. `AB5` measured the group generated by the accumulator maps that erase
 * nothing — `ADD` over every operand plus `NEG` — and found order exactly 1,458 on
 * 729 states. That group has a name: run the identical construction on twelve
 * points and it returns 24, the dihedral group musical set theory has called **T/I**
 * since the 1960s. This project rebuilt it without knowing, and reached the same
 * conclusion from the other side.
 *
 * The check worth keeping is `AE3`. Four figures — 224 set classes, 12 trichords,
 * 29 tetrachords, 50 hexachords — are published musicology that was **not derived
 * here**, and the audit reproduces all four before its ternary answers are looked
 * at. An instrument that agrees with sixty years of counting on the case where the
 * answer is known has earned the case where it is not.
 *
 * `AE4` failed on a threshold and held on its ratio, which is a lesson in itself.
 *
 * The exhaustive version is `npm run audit:setclass`.
 */

const S = require('../tools/setclass-audit.js');
const { chainOf } = require('../tools/perm-lib.js');
const { execFileSync } = require('child_process');
const path = require('path');

let pass = 0; const fails = [];
const check = (name, cond, detail = '') => {
  if (cond) { pass++; console.log(`  [PASS] ${name}`); }
  else { fails.push(name); console.log(`  [FAIL] ${name}  ${detail}`); }
};

console.log('\n=== 0. THE INSTRUMENT, BEFORE ANY FINDING ===');
{
  check('T_1 on Z/12 is a single twelve-cycle', S.cycles(S.T(12, 1)) === 1);
  check('T_0 is the identity, so twelve fixed points', S.cycles(S.T(12, 0)) === 12);
  check('T_6 on Z/12 is six two-cycles — the tritone pairing',
    S.cycles(S.T(12, 6)) === 6);
  check('inversion on Z/12 fixes 0 and 6 and swaps the other ten in pairs',
    S.cycles(S.I(12)) === 7);
  check('the T/I group lists 24 elements and they are 24 DISTINCT permutations',
    S.TIgroup(12).length === 24 && new Set(S.TIgroup(12).map(g => g.join(','))).size === 24);
  check('Burnside reproduces a case checkable by hand: two-colour necklaces of ' +
    'length four under rotation number 6',
    [0, 1, 2, 3].map(k => S.T(4, k)).reduce((s, g) => s + 2 ** S.cycles(g), 0) / 4 === 6);
  check('and the harness would notice a wrong cycle count: T_6 is not a twelve-cycle',
    S.cycles(S.T(12, 6)) !== 1);
}

console.log('\n=== 0b. THE TOOL AS IT IS ACTUALLY RUN ===');
{
  let out = '', code = 0;
  try {
    out = execFileSync(process.execPath,
      [path.join(__dirname, '..', 'tools', 'setclass-audit.js')], { encoding: 'utf8' });
  } catch (e) { code = 1; out = (e.stdout || '') + (e.message || ''); }
  check('the audit runs to completion as a program, not only as an import',
    code === 0, out.split('\n').slice(-3).join(' | '));
  check('and all four sections printed, so every log path executed',
    [/1\. AE1/, /2\. AE2/, /3\. AE3/, /4\. AE4/].every(r => r.test(out)));
}

console.log('\n=== 1. AE1 — AB5 MEASURED THE T/I GROUP ===');
{
  const order = n => chainOf([S.T(n, 1), S.I(n)], n).order;
  check('translation-by-1 and negation on Z/12 generate exactly 24 — the group ' +
    'musical set theory calls T/I', order(12) === 24n, `${order(12)}`);
  check('the same two generators on Z/27 give 54', order(27) === 54n);
  check('and on Z/729 they give 1,458 — the number AB5 recorded for the ' +
    'zero-erasure ALU fragment', order(729) === 1458n);
  check('so the answer is 2n at every width, and the tryte is not special',
    [12, 27, 729].every(n => order(n) === BigInt(2 * n)));
  check('the generators are literally the same construction, not an analogy: ' +
    'transposition is ADD and inversion is NEG',
    S.T(729, 1)[0] === 1 && S.I(729)[1] === 728);
}

console.log('\n=== 2. AE2 — A PRIME POWER IS DIVISOR-POOR ===');
{
  const lengths = n => new Set(Array.from({ length: n },
    (_, k) => n / S.gcd(k === 0 ? n : k, n)));
  check('distinct translation orbit-lengths equal the divisor count, exactly, at every n',
    [12, 27, 720, 729].every(n => lengths(n).size === S.divisors(n).length));
  check('Z/12 has 6 and Z/27 has 4', lengths(12).size === 6 && lengths(27).size === 4);
  check('720 and 729 are ONE APART, and have 30 divisors against 7',
    S.divisors(720).length === 30 && S.divisors(729).length === 7);
  check('every Z/3^k period is a power of three, so consecutive periods differ by ' +
    'exactly 3 and nothing sits between them',
    [...lengths(729)].every(v => 3 ** Math.round(Math.log(v) / Math.log(3)) === v));
  check('so Z/27 has no analogue of the whole-tone scale (period 6) or the ' +
    'diminished seventh (period 4) — 6 and 4 do not divide 27',
    !lengths(27).has(6) && !lengths(27).has(4) && lengths(12).has(6) && lengths(12).has(4));
}

console.log('\n=== 3. AE3 — THE CONTROL: PUBLISHED MUSICOLOGY, REPRODUCED ===');
{
  const c12 = S.setClasses(12), card12 = S.byCardinality(12);
  check('Z/12 has exactly 224 set classes under T/I — the published figure',
    c12 === 224n, `${c12}`);
  check('12 trichord classes', card12[3] === 12n, `${card12[3]}`);
  check('29 tetrachord classes', card12[4] === 29n, `${card12[4]}`);
  check('50 hexachord classes', card12[6] === 50n, `${card12[6]}`);
  check('four figures this project did not derive, all reproduced before the ' +
    'ternary answers were looked at',
    c12 === 224n && card12[3] === 12n && card12[4] === 29n && card12[6] === 50n);
  check('the cardinalities sum to the total, so nothing was dropped',
    card12.reduce((a, b) => a + b, 0n) === c12);

  const c27 = S.setClasses(27);
  check('Z/27 lands at 2,493,726 set classes, inside the predicted 2.4-2.6 million',
    c27 === 2493726n && c27 > 2400000n && c27 < 2600000n, `${c27}`);
  check('which is close to 2^27 / 54, because the identity dominates the average at ' +
    'that size', Number(c27) / Number(2n ** 27n / 54n) < 1.01);
  const card27 = S.byCardinality(27);
  check('and Z/27 has 61 trichord classes against Z/12\'s 12 — MORE raw variety',
    card27[3] === 61n && card27[3] > card12[3], `${card27[3]}`);
}

console.log('\n=== 4. AE4 — FAILED ON THE THRESHOLD, HELD ON THE RATIO ===');
{
  const a = S.symmetricFraction(12), b = S.symmetricFraction(27);
  const fa = a.count / a.total, fb = b.count / b.total;
  check('Z/12 has 74 subsets with nontrivial transpositional symmetry, out of 4,096',
    a.count === 74 && a.total === 4096, `${a.count}/${a.total}`);
  check('AE4 FAILED and stays failed: that is 1.81%, under the predicted 2%',
    fa < 0.02 && Math.abs(100 * fa - 1.81) < 0.01, `${(100 * fa).toFixed(3)}%`);
  check('the Z/27 clause HELD: 510 of 134,217,728, which is 0.00038%',
    b.count === 510 && fb < 0.00001, `${b.count} ${(100 * fb).toPrecision(3)}%`);
  check('and the ratio clause HELD: Z/12 is 4,755x richer, 3.7 orders of magnitude',
    fa / fb > 1000 && Math.abs(fa / fb - 4755) < 5, `${(fa / fb).toFixed(0)}x`);
  check('so the direction and the magnitude both survived a threshold that did not — ' +
    'a number picked to sound decisive is a worse prediction than the ratio it stands for',
    fa / fb > 1000 && fa < 0.02);
  check('ternary is richer in variety and poorer in structure at the same time: ' +
    'five times the trichord classes, four thousand times fewer symmetric subsets',
    S.byCardinality(27)[3] > S.byCardinality(12)[3] && fa / fb > 1000);
}

console.log(`\n${'='.repeat(64)}`);
console.log(fails.length ? `${fails.length} CHECK(S) FAILED:\n  ${fails.join('\n  ')}` : `ALL ${pass} CHECKS PASSED`);
console.log('='.repeat(64));
process.exit(fails.length ? 1 : 0);
